package com.hostelcare.entity;
import com.hostelcare.enums.*; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="complaints")
public class Complaint { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) @Column(name="complaint_id") public Long complaintId; @ManyToOne(optional=false) @JoinColumn(name="student_id") public User student; @ManyToOne(optional=false) @JoinColumn(name="room_id") public Room room; @ManyToOne(optional=false) @JoinColumn(name="category_id") public Category category; @Column(nullable=false,length=150) public String title; @Column(nullable=false,columnDefinition="TEXT") public String description; @Enumerated(EnumType.STRING) @Column(length=20) public Priority priority; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) public ComplaintStatus status=ComplaintStatus.SUBMITTED; @Column(name="created_at",nullable=false) public LocalDateTime createdAt=LocalDateTime.now(); @Column(name="updated_at",nullable=false) public LocalDateTime updatedAt=LocalDateTime.now(); }
